**Interfaces:**

- Consumes: `deviceFlow`, `refresh`, `needsRenewal`, `configDir`, `readSession`, `writeSession`, `forgetSession` from `@runlog/session`; `GET /api/auth/deck` from Task 3.
- Produces:

```ts
export interface Account { apiBase: string }
export function sessionDir(): string;                                    // configDir("runlog-deck")
export function loadSession(): Session | null;
export function signIn(account: Account, say: (line: string) => void, open: (url: string) => void): Promise<Session>;
export function bearer(account: Account): Promise<string | null>;        // renews when needed, null when signed out or refresh refused
export function signOut(): void;
```

- [ ] **Step 1: Write the failing test**

```ts
import { describe, expect, it, vi } from "vitest";
import { bearer, signIn } from "./session.ts";

describe("the deck's session", () => {
  it("signs in through the device flow against the deck's own client", async () => {
    const fetch = vi.fn(async (url: string) => {
      if (String(url).endsWith("/api/auth/deck")) return new Response(JSON.stringify({ clientId: "client_deck", issuer: "https://api.workos.com" }));
      if (String(url).includes("/authorize/device")) return new Response(JSON.stringify({ device_code: "d", user_code: "ABCD-EFGH", verification_uri: "https://x/y", interval: 0, expires_in: 60 }));
