    const said: string[] = [];
    const s = await signIn({ apiBase: "https://api.test" }, (l) => said.push(l), () => {});
    expect(s.clientId).toBe("client_deck");
    expect(said.join("\n")).toContain("ABCD-EFGH");
  });
