```

- [ ] **Step 2: Run test to verify it fails**

Run: `npx vitest run streamdeck/src/session.test.ts`
Expected: FAIL — cannot resolve `./session.ts`.

- [ ] **Step 3: Write it**

```ts
import { configDir, deviceFlow, forgetSession, needsRenewal, readSession, refresh, writeSession, type Session } from "@runlog/session";

export interface Account {
  apiBase: string;
}

/**
 * The deck's session, kept in a file of the plugin's own.
 *
 * Not in Stream Deck's global settings: those are handed to the property
 * inspector, which is a web view, and a refresh token is the one thing
 * this plugin holds that must never be. The CLI keeps its session the
 * same way, in the same directory tree, under a different name.
 */
export function sessionDir(): string {
  return configDir("runlog-deck");
}

export function loadSession(): Session | null {
  return readSession(sessionDir());
}

export function signOut(): void {
  forgetSession(sessionDir());
}

async function clientOf(account: Account): Promise<{ clientId: string; issuer: string }> {
  const res = await fetch(`${account.apiBase}/api/auth/deck`);
  const body = (await res.json()) as { clientId?: string | null; issuer?: string };
  if (!body.clientId) throw new Error("this copy of Runlog has no sign-in for a deck");
  return { clientId: body.clientId, issuer: body.issuer ?? "https://api.workos.com" };
}

export async function signIn(account: Account, say: (line: string) => void, open: (url: string) => void): Promise<Session> {
  const { clientId, issuer } = await clientOf(account);
  const session = await deviceFlow(clientId, issuer, {
    fetch: (input, init) => fetch(input, init),
    sleep: (ms) => new Promise((r) => setTimeout(r, ms)),
    say,
    open,
    now: () => Date.now(),
  });
  writeSession(sessionDir(), session);
  return session;
}

/** The bearer to send, renewed first when it is about to lapse; null means sign in. */
export async function bearer(_account: Account): Promise<string | null> {
  const session = loadSession();
  if (!session) return null;
  if (!needsRenewal(session, Date.now())) return session.accessToken;
  try {
    const renewed = await refresh(session);
    writeSession(sessionDir(), renewed);
    return renewed.accessToken;
  } catch {
    // A refresh the issuer refused is a session that is over. Leave the
    // file so a retry after a network blip is not a full sign-in, and
    // let the caller read the null as "Sign in again".
    return null;
  }
}
```

- [ ] **Step 4: The inspector's sign-in block**

`ui/signin.html` is a fragment every action's inspector includes at the top (sdpi-components v4):

```html
<sdpi-item label="Account">
  <sdpi-button id="signin">Sign in</sdpi-button>
  <span id="who"></span>
</sdpi-item>
<sdpi-item id="code-row" hidden label="Your code">
  <strong id="code"></strong> · <a id="link" target="_blank">Open the sign-in page</a>
</sdpi-item>
<script>
  const { streamDeckClient } = SDPIComponents;
  document.getElementById("signin").addEventListener("click", () => streamDeckClient.send("sendToPlugin", { t: "signin" }));
  streamDeckClient.on("sendToPropertyInspector", ({ payload }) => {
    if (payload.t === "code") {
      document.getElementById("code-row").hidden = false;
      document.getElementById("code").textContent = payload.code;
      document.getElementById("link").href = payload.url;
    }
    if (payload.t === "who") {
      document.getElementById("code-row").hidden = true;
      document.getElementById("who").textContent = payload.name ? `Signed in as ${payload.name}` : "Not signed in";
    }
  });
</script>
```

The plugin side (Task 10) answers `{ t: "signin" }` by calling `signIn` with `say` parsing the code line into `{ t: "code", code, url }` and posting it with `streamDeck.ui.sendToPropertyInspector`.

