```bash
npx vitest run streamdeck && npm run typecheck
git add streamdeck/src/session.ts streamdeck/src/session.test.ts streamdeck/com.scrthq.runlog.sdPlugin/ui/signin.html
git commit -m "feat(deck): the plugin signs in and keeps its session to itself"
```

